module Top;
    int down[3:0];
    byte bytes[2:5] = '{1, -2, 3, -4};
    int r[$];
    byte b[$];
    initial begin
        down[3] = 1; down[2] = 5; down[1] = 5; down[0] = 2;
        r = down.find_first_index with (item == 5);
        $display("down first=%0d", r[0]);
        r = bytes.find_index with (item < 0);
        $display("bytes negative at %0d %0d", r[0], r[1]);
        b = bytes.min;
        $display("bytes min=%0d", b[0]);
        b = bytes.find_first with (item.index == 4);
        $display("bytes[4] found=%0d", b.size());
    end
endmodule
